				R.style.TextAppearance_Kotatsu_GridTitle
			}
			if (textAppearanceResId != prevTextAppearance) {
				prevTextAppearance = textAppearanceResId
				setTextAppearance(textAppearanceResId)
				requestLayout()
			}
		}
	}
}

