// EnvironmentPackages
object EnvPackages {
    val ActionShowAppInfo: String
        get() = if (OsUtils.satisfy(OsUtils.N)) Intent.ACTION_SHOW_APP_INFO
        else "android.intent.action.SHOW_APP_INFO"
