object TypeConverterUtil{

    @TypeConverter
    @JvmStatic
    fun toBoolean(value: Boolean): String{
        return value.toString()
    }

    @TypeConverter
    @JvmStatic
    fun fromBoolean(value: String): Boolean{
        return value.toBoolean()
    }

    @TypeConverter
    @JvmStatic
    fun fromBigDecimal(value: BigDecimal): String{
        return value.toPlainString()
    }

    @TypeConverter
    @JvmStatic
    fun toBigDecimal(value: String?): BigDecimal{
        return value?.toBigDecimal() ?: 0.toBigDecimal()
    }

    @TypeConverter
    @JvmStatic
    fun fromString(value: List<String>?): String{
        val type = Types.newParameterizedType(List::class.java, String::class.java)
        val adapter: JsonAdapter<List<String>> = Moshi.Builder().build().adapter(type)
        return adapter.toJson(value)
    }

    @TypeConverter
    @JvmStatic
    fun toList(value: String): List<String>{
        val type = Types.newParameterizedType(List::class.java, String::class.java)
        val adapter: JsonAdapter<List<String>> = Moshi.Builder().build().adapter(type)
        return adapter.fromJson(value) ?: arrayListOf()
    }

    @TypeConverter
    @JvmStatic
    fun fromTimestamp(value: Long?): OffsetDateTime? {
        return OffsetDateTime.ofInstant(Instant.ofEpochMilli(value ?: 0), ZoneId.systemDefault())
    }

    @TypeConverter
    @JvmStatic
    fun dateToTimestamp(date: OffsetDateTime?): Long? {
        return date?.toInstant()?.toEpochMilli()
    }

    @TypeConverter
    @JvmStatic
    fun fromLocalDate(value: String?): LocalDate? {
        return LocalDate.parse(value)
    }

    @TypeConverter
    @JvmStatic
    fun toLocalDate(value: LocalDate?): String {
        return value.toString()
    }

    @TypeConverter
    @JvmStatic
    fun fromUri(value: String?): Uri? {
        return value?.toUri()
    }

    @TypeConverter
    @JvmStatic
    fun toUri(value: Uri?): String? {
        return value?.toString()
    }

    @TypeConverter
    @JvmStatic
    fun fromBudgetType(value: String?): BudgetType? {
        if(value == null){
            return null
        }
        if(value.contentEquals("none")){
            return BudgetType.NONE
        } else if(value.contentEquals("

middle:
rollover")){
            return BudgetType.ROLLOVER
        } else if(value.contentEquals("reset")){
            return BudgetType.RESET
        }
        return null
