                    val action = action.copy()
                    action.postId = postId
                    action.body = str
                    commentViewModel.createCommment(action)
                }
            }
            .setNegativeButton(R.string.comment_cancel, null)
            .setView(layout)
            .create()
            .show()
    }

    private fun delete(id: Int) {
        val action = action.copy()
        action.commentId = id
        commentViewModel.deleteComment(action)
    }
