                            clipboardManager?.setPrimaryClip(ClipData.newPlainText("RepoUrl", repositoryData.url))
                            if (Build.VERSION.SDK_INT <=

suffix:
                            }
                            return@setOnLongClickListener true
                        }

                        mainText.text = repositoryData.name
